DO $$ DECLARE r record; v_acl text; BEGIN FOR r IN SELECT p.proname, pg_get_function_identity_arguments(p.oid) AS args, p.proconfig, p.proacl, pg_get_functiondef(p.oid) AS definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('upsert_holding_buy','upsert_holding_sell','adjust_cash_balance') LOOP IF NOT (r.proconfig::text LIKE '%search_path=public, pg_temp%') THEN RAISE EXCEPTION 'missing explicit search_path for % (%)', r.proname, r.args; END IF; v_acl := coalesce(array_to_string(r.proacl, ', '), ''); IF v_acl ~ 'anon=X' OR v_acl ~ ' =X' THEN RAISE EXCEPTION 'unexpected anonymous/public execute grant for %: %', r.proname, v_acl; END IF; END LOOP; END $$;
